# 40_tables.R: summary tables (no refitting). Medians and central 95% intervals over the 50 replicates; Wilcoxon/sign p-values descriptive only and uncorrected. Run from final/.
suppressMessages({library(dplyr); library(tidyr)}); OUT <- "revision_ident/tables"; q <- function(x, p) unname(quantile(x, p, type = 7, na.rm = TRUE)); wp <- function(x) if (sum(is.finite(x) & x != 0) < 5) NA_real_ else suppressWarnings(wilcox.test(x, mu = 0)$p.value)
# ---------------- Part B: balanced known-parameter simulation ----------------
B <- read.csv(file.path(OUT, "balancedB_fits.csv")); Ag <- read.csv(file.path(OUT, "balancedB_optimiser_agreement.csv"))
write.csv(Ag |> group_by(arm, exact, order, model, stage) |> summarise(n = n(), median_max_coef_diff = median(max_coef_diff_pkg_vs_indep), median_max_pred_diff = median(max_pred_diff_pkg_vs_indep), p95_max_pred_diff = q(max_pred_diff_pkg_vs_indep, .95), median_obj_diff = median(obj_diff), prop_pred_diff_lt_1e3 = mean(max_pred_diff_pkg_vs_indep < 1e-3), .groups = "drop"), file.path(OUT, "balancedB_summary_optimiser_agreement.csv"), row.names = FALSE)
write.csv(B |> filter(optimiser == "pkg") |> group_by(order, model) |> summarise(rank = median(rank), n_parameters = median(n_parameters), scaled_condition_median = median(scaled_condition), .groups = "drop"), file.path(OUT, "balancedB_summary_rank.csv"), row.names = FALSE)
Ex <- B |> filter(exact, optimiser == "pkg") |> select(arm, scenario, order, model, stage, rank, n_parameters, scaled_condition, D2_test, D2_oracle, rmse_link_vs_truth, rmse_resp_vs_truth, outside_sd_est, outside_sd_true, outside_cor, outside_rmse, delta_sum_est, delta_sum_true, delta_rmse, est_link_did_explicit, true_link_did_explicit, est_resp_did_explicit, true_resp_did_explicit, est_link_did, true_link_did, est_resp_did, true_resp_did); write.csv(Ex, file.path(OUT, "balancedB_summary_exact.csv"), row.names = FALSE)
N <- B |> filter(!exact, optimiser == "pkg"); W <- N |> select(arm, scenario, order, replicate, model, stage, D2_test) |> pivot_wider(names_from = c(model, stage), values_from = D2_test, names_sep = "__")
gn <- function(a, b) W |> mutate(g = .data[[a]] - .data[[b]]) |> group_by(arm, scenario, order) |> summarise(median = median(g, na.rm = TRUE), q025 = q(g, .025), q975 = q(g, .975), n = sum(is.finite(g)), n_positive = sum(g > 0, na.rm = TRUE), wilcoxon_p = wp(g), .groups = "drop")
G <- bind_rows(lapply(list(c("interaction__unpenalised", "additive__unpenalised", "unpenalised"), c("interaction__ridge", "additive__ridge", "ridge"), c("interaction__curvature", "additive__curvature", "curvature"), c("interaction__shrink", "additive__curvature", "shrink 5e-3"), c("interaction__weakshrink", "additive__curvature", "shrink 1e-6"), c("interaction__selected", "additive__selected", "jointly selected")), function(z) cbind(gn(z[1], z[2]), stage = z[3]))); write.csv(G, file.path(OUT, "balancedB_summary_gains.csv"), row.names = FALSE)
Ni <- N |> filter(model == "interaction") |> group_by(arm, scenario, order, stage) |> summarise(outside_sd_est_median = median(outside_sd_est), outside_sd_est_q975 = q(outside_sd_est, .975), outside_sd_true = median(outside_sd_true), outside_cor_median = median(outside_cor, na.rm = TRUE), outside_rmse_median = median(outside_rmse), est_explicit_link_did_median = median(est_link_did_explicit), est_explicit_link_did_q025 = q(est_link_did_explicit, .025), est_explicit_link_did_q975 = q(est_link_did_explicit, .975), true_explicit_link_did = median(true_link_did_explicit), est_explicit_resp_did_median = median(est_resp_did_explicit), true_explicit_resp_did = median(true_resp_did_explicit), bias_explicit_link_did = median(est_link_did_explicit - true_link_did_explicit), rmse_explicit_link_did = sqrt(mean((est_link_did_explicit - true_link_did_explicit)^2)), delta_rmse_median = median(delta_rmse), delta_sum_est_median = median(delta_sum_est), delta_sum_true = median(delta_sum_true), rank = median(rank), n_parameters = median(n_parameters), scaled_condition_median = median(scaled_condition), n = n(), .groups = "drop"); write.csv(Ni, file.path(OUT, "balancedB_summary_interaction_recovery.csv"), row.names = FALSE)
write.csv(N |> group_by(arm, scenario, order, model, stage) |> summarise(D2_test_median = median(D2_test), D2_oracle_median = median(D2_oracle), rmse_link_median = median(rmse_link_vs_truth), rmse_resp_median = median(rmse_resp_vs_truth), n_converged = sum(converged), n = n(), .groups = "drop"), file.path(OUT, "balancedB_summary_performance.csv"), row.names = FALSE)
sel <- N |> filter(stage == "selected") |> group_by(arm, scenario, order, model) |> summarise(median_sel_spread_smooth = median(sel_spread_smooth), prop_sel_shrink_5e3 = mean(sel_interaction_shrink == 5e-3, na.rm = TRUE), prop_sel_shrink_1e4 = mean(sel_interaction_shrink == 1e-4, na.rm = TRUE), prop_sel_shrink_1e6 = mean(sel_interaction_shrink == 1e-6, na.rm = TRUE), .groups = "drop"); write.csv(sel, file.path(OUT, "balancedB_summary_selected_penalties.csv"), row.names = FALSE)
# ---------------- Part C: metacommunity ----------------
M <- read.csv(file.path(OUT, "meta_fits.csv")); wm <- M |> select(scenario, replicate, order, arm, response, config, D2_test) |> pivot_wider(names_from = config, values_from = D2_test); grp <- c("scenario", "order", "arm", "response")
gm <- function(a, b) wm |> mutate(g = .data[[a]] - .data[[b]]) |> group_by(across(all_of(grp))) |> summarise(median = median(g, na.rm = TRUE), q025 = q(g, .025), q975 = q(g, .975), n_positive = sum(g > 0, na.rm = TRUE), n = sum(is.finite(g)), wilcoxon_p = wp(g), .groups = "drop")
GM <- bind_rows(lapply(list(c("additive", "spread_only"), c("same_5e-03", "additive"), c("same_1e-06", "additive"), c("cross_5e-03", "additive"), c("cross_1e-06", "additive"), c("cross_1e-06", "same_1e-06"), c("cross_5e-03", "same_5e-03")), function(z) cbind(gm(z[1], z[2]), contrast = paste(z[1], "minus", z[2])))); write.csv(GM, file.path(OUT, "meta_summary_gains.csv"), row.names = FALSE)
write.csv(M |> group_by(across(all_of(c(grp, "config")))) |> summarise(D2_test_median = median(D2_test), D2_test_q025 = q(D2_test, .025), D2_test_q975 = q(D2_test, .975), rmse_link_median = median(rmse_link), rmse_resp_median = median(rmse_resp), rank = median(rank), n_parameters = median(n_parameters), scaled_condition_median = median(scaled_condition), n_train_sets_median = median(n_train_sets), n_cells_filled_median = median(n_cells_filled, na.rm = TRUE), n_converged = sum(converged), n = n(), .groups = "drop"), file.path(OUT, "meta_summary_performance.csv"), row.names = FALSE)
ct <- function(sc) M |> group_by(across(all_of(c(grp, "config")))) |> summarise(true = median(.data[[paste0("true_", sc)]]), est_median = median(.data[[paste0("est_", sc)]]), est_q025 = q(.data[[paste0("est_", sc)]], .025), est_q975 = q(.data[[paste0("est_", sc)]], .975), bias = mean(.data[[paste0("est_", sc)]] - .data[[paste0("true_", sc)]]), rmse = sqrt(mean((.data[[paste0("est_", sc)]] - .data[[paste0("true_", sc)]])^2)), prop_correct_sign = mean(sign(.data[[paste0("est_", sc)]]) == sign(.data[[paste0("true_", sc)]]) & abs(.data[[paste0("est_", sc)]]) > 1e-3), prop_abs_gt_0.1 = mean(abs(.data[[paste0("est_", sc)]]) > .1), .groups = "drop") |> mutate(contrast = sc)
write.csv(bind_rows(lapply(c("link_did_P", "resp_did_P", "link_did_X", "resp_did_X"), ct)), file.path(OUT, "meta_summary_contrasts.csv"), row.names = FALSE)
write.csv(M |> filter(config %in% c("same_1e-06", "cross_1e-06", "same_5e-03", "cross_5e-03")) |> group_by(scenario, order, arm, config) |> summarise(outside_sd_median = median(outside_sd_est, na.rm = TRUE), outside_sd_q975 = q(outside_sd_est, .975), .groups = "drop"), file.path(OUT, "meta_summary_outside_additive.csv"), row.names = FALSE)
write.csv(M |> group_by(config) |> summarise(n_fits = n(), n_nonconverged = sum(!converged), .groups = "drop"), file.path(OUT, "meta_summary_convergence.csv"), row.names = FALSE)
options(width = 230, digits = 3); print(GM |> filter(response == "relative", arm == "balanced", contrast %in% c("cross_1e-06 minus additive", "same_1e-06 minus additive", "cross_5e-03 minus additive")) |> select(scenario, order, contrast, median, q025, q975, n_positive) |> as.data.frame())
